inductive ZigExpr where
  | Var (name : Nat)
  | Const (val : Nat)
  | Add (a b : ZigExpr)
  | Mul (a b : ZigExpr)

def evalZig (env : Nat → Nat) : ZigExpr → Nat
  | ZigExpr.Var n => env n
  | ZigExpr.Const v => v
  | ZigExpr.Add a b => evalZig env a + evalZig env b
  | ZigExpr.Mul a b => evalZig env a * evalZig env b

def zig_rmsnorm_inner (x w : Nat) : ZigExpr :=
  ZigExpr.Mul (ZigExpr.Mul (ZigExpr.Var x) (ZigExpr.Const 35)) (ZigExpr.Var w)

def lean_rmsnorm_inner (env : Nat → Nat) (x w : Nat) : Nat :=
  env x * 35 * env w

theorem zig_lean_isomorphism (env : Nat → Nat) (x w : Nat) :
  evalZig env (zig_rmsnorm_inner x w) = lean_rmsnorm_inner env x w := by
  rfl

