const std = @import("std");

pub const V16 = @Vector(16, f32);
pub const V16_u16 = @Vector(16, u16);
pub const V16_u32 = @Vector(16, u32);

pub inline fn bf16ToF32(bits: u16) f32 {
    const raw: u32 = @as(u32, bits) << 16;
    return @bitCast(raw);
}

pub inline fn f32ToBf16(value: f32) u16 {
    const raw: u32 = @bitCast(value);
    const exponent = raw & 0x7F80_0000;
    const mantissa = raw & 0x007F_FFFF;
    if (exponent == 0x7F80_0000) {
        if (mantissa != 0) {
            const quieted = (raw >> 16) | 0x0040 | @as(u32, @intFromBool((raw & 0x0000_FFFF) != 0));
            return @truncate(quieted);
        }
        return @truncate(raw >> 16);
    }
    const lsb: u32 = (raw >> 16) & 1;
    const rounded: u32 = raw + 0x7FFF + lsb;
    return @truncate(rounded >> 16);
}

pub inline fn bf16x16_to_f32x16(v: V16_u16) V16 {
    var lanes: [16]f32 = undefined;
    inline for (0..16) |lane| {
        lanes[lane] = bf16ToF32(v[lane]);
    }
    const result: V16 = lanes;
    return result;
}

pub inline fn f32x16_to_bf16x16(v: V16) V16_u16 {
    var lanes: [16]u16 = undefined;
    inline for (0..16) |lane| {
        lanes[lane] = f32ToBf16(v[lane]);
    }
    const result: V16_u16 = lanes;
    return result;
}

inline fn loadF32x16(buffer: anytype, offset: usize) V16 {
    var lanes: [16]f32 = undefined;
    inline for (0..16) |lane| {
        lanes[lane] = bf16ToF32(buffer[offset + lane]);
    }
    const result: V16 = lanes;
    return result;
}

inline fn storeF32x16(buffer: anytype, offset: usize, values: V16) void {
    inline for (0..16) |lane| {
        buffer[offset + lane] = f32ToBf16(values[lane]);
    }
}

inline fn exp16(values: V16) V16 {
    var lanes: [16]f32 = undefined;
    inline for (0..16) |lane| {
        lanes[lane] = @exp(values[lane]);
    }
    const result: V16 = lanes;
    return result;
}

inline fn safeInvSqrt(value: f32) f32 {
    return if (value <= 0.0) 0.0 else 1.0 / @sqrt(value);
}

inline fn tanhApprox16(values: V16) V16 {
    const one: V16 = @splat(1.0);
    const two: V16 = @splat(2.0);
    const limit: V16 = @splat(9.0);
    const neg_limit: V16 = @splat(-9.0);
    const clamped = @max(neg_limit, @min(limit, values));
    const e2x = exp16(clamped * two);
    return (e2x - one) / (e2x + one);
}

inline fn tanhApproxScalar(value: f32) f32 {
    const clamped = @max(@as(f32, -9.0), @min(@as(f32, 9.0), value));
    const e2x = @exp(2.0 * clamped);
    return (e2x - 1.0) / (e2x + 1.0);
}

pub fn rmsNormForward(comptime N: usize, input: *const [N]u16, weight: *const [N]u16, output: *[N]u16, eps: f32) void {
    if (N == 0) return;
    const full = (N / 16) * 16;
    var sum_sq: V16 = @splat(0.0);
    var offset: usize = 0;

    while (offset < full) : (offset += 16) {
        const x = loadF32x16(input, offset);
        sum_sq += x * x;
    }

    var total_sum = @reduce(.Add, sum_sq);
    while (offset < N) : (offset += 1) {
        const x = bf16ToF32(input[offset]);
        total_sum += x * x;
    }

    const n_f32: f32 = @floatFromInt(N);
    const inv_rms = safeInvSqrt((total_sum / n_f32) + eps);
    const inv_rms_vec: V16 = @splat(inv_rms);

    offset = 0;
    while (offset < full) : (offset += 16) {
        const x = loadF32x16(input, offset);
        const w = loadF32x16(weight, offset);
        storeF32x16(output, offset, x * inv_rms_vec * w);
    }

    while (offset < N) : (offset += 1) {
        const x = bf16ToF32(input[offset]);
        const w = bf16ToF32(weight[offset]);
        output[offset] = f32ToBf16(x * inv_rms * w);
    }
}

pub fn layerNormForward(comptime N: usize, input: *const [N]u16, weight: *const [N]u16, bias: *const [N]u16, output: *[N]u16, eps: f32) void {
    if (N == 0) return;
    const full = (N / 16) * 16;
    var sum: V16 = @splat(0.0);
    var sum_sq: V16 = @splat(0.0);
    var offset: usize = 0;

    while (offset < full) : (offset += 16) {
        const x = loadF32x16(input, offset);
        sum += x;
        sum_sq += x * x;
    }

    var total_sum = @reduce(.Add, sum);
    var total_sum_sq = @reduce(.Add, sum_sq);
    while (offset < N) : (offset += 1) {
        const x = bf16ToF32(input[offset]);
        total_sum += x;
        total_sum_sq += x * x;
    }

    const n_f32: f32 = @floatFromInt(N);
    const mean = total_sum / n_f32;
    const mean_sq = total_sum_sq / n_f32;
    const variance = @max(mean_sq - (mean * mean), @as(f32, 0.0));
    const inv_std = safeInvSqrt(variance + eps);
    const mean_vec: V16 = @splat(mean);
    const inv_std_vec: V16 = @splat(inv_std);

    offset = 0;
    while (offset < full) : (offset += 16) {
        const x = loadF32x16(input, offset);
        const w = loadF32x16(weight, offset);
        const b = loadF32x16(bias, offset);
        const centered = x - mean_vec;
        const normalized = centered * inv_std_vec;
        storeF32x16(output, offset, (normalized * w) + b);
    }

    while (offset < N) : (offset += 1) {
        const x = bf16ToF32(input[offset]);
        const w = bf16ToF32(weight[offset]);
        const b = bf16ToF32(bias[offset]);
        output[offset] = f32ToBf16(((x - mean) * inv_std * w) + b);
    }
}

pub fn geluForward(comptime N: usize, input: *const [N]u16, output: *[N]u16) void {
    const full = (N / 16) * 16;
    const sqrt_2_over_pi: V16 = @splat(0.7978845608028654);
    const coeff_0_044715: V16 = @splat(0.044715);
    const half: V16 = @splat(0.5);
    const one: V16 = @splat(1.0);
    var offset: usize = 0;

    while (offset < full) : (offset += 16) {
        const x = loadF32x16(input, offset);
        const x2 = x * x;
        const x3 = x2 * x;
        const tanh_arg = sqrt_2_over_pi * (x + (coeff_0_044715 * x3));
        const tanh_val = tanhApprox16(tanh_arg);
        storeF32x16(output, offset, half * x * (one + tanh_val));
    }

    while (offset < N) : (offset += 1) {
        const x = bf16ToF32(input[offset]);
        const tanh_arg = 0.7978845608028654 * (x + 0.044715 * x * x * x);
        const tanh_val = tanhApproxScalar(tanh_arg);
        output[offset] = f32ToBf16(0.5 * x * (1.0 + tanh_val));
    }
}

pub fn softmaxForward(comptime N: usize, input: *const [N]u16, output: *[N]u16) void {
    if (N == 0) return;
    const full = (N / 16) * 16;
    var max_vec: V16 = @splat(-std.math.inf(f32));
    var offset: usize = 0;

    while (offset < full) : (offset += 16) {
        max_vec = @max(max_vec, loadF32x16(input, offset));
    }

    var max_val = @reduce(.Max, max_vec);
    while (offset < N) : (offset += 1) {
        max_val = @max(max_val, bf16ToF32(input[offset]));
    }

    const max_splat: V16 = @splat(max_val);
    var sum_exp_vec: V16 = @splat(0.0);

    offset = 0;
    while (offset < full) : (offset += 16) {
        const shifted = loadF32x16(input, offset) - max_splat;
        sum_exp_vec += exp16(shifted);
    }

    var total_sum_exp = @reduce(.Add, sum_exp_vec);
    while (offset < N) : (offset += 1) {
        total_sum_exp += @exp(bf16ToF32(input[offset]) - max_val);
    }

    const inv_sum = 1.0 / total_sum_exp;
    const inv_sum_vec: V16 = @splat(inv_sum);

    offset = 0;
    while (offset < full) : (offset += 16) {
        const shifted = loadF32x16(input, offset) - max_splat;
        storeF32x16(output, offset, exp16(shifted) * inv_sum_vec);
    }

    while (offset < N) : (offset += 1) {
        output[offset] = f32ToBf16(@exp(bf16ToF32(input[offset]) - max_val) * inv_sum);
    }
}

pub fn rmsNormBackward(comptime N: usize, grad_output: *const [N]u16, input: *const [N]u16, weight: *const [N]u16, grad_input: *[N]u16, grad_weight: *[N]u16, eps: f32) void {
    if (N == 0) return;
    const full = (N / 16) * 16;
    var sum_sq: V16 = @splat(0.0);
    var offset: usize = 0;

    while (offset < full) : (offset += 16) {
        const x = loadF32x16(input, offset);
        sum_sq += x * x;
    }

    var total_sum_sq = @reduce(.Add, sum_sq);
    while (offset < N) : (offset += 1) {
        const x = bf16ToF32(input[offset]);
        total_sum_sq += x * x;
    }

    const n_f32: f32 = @floatFromInt(N);
    const inv_rms = safeInvSqrt((total_sum_sq / n_f32) + eps);
    const inv_rms_cubed = inv_rms * inv_rms * inv_rms;
    const inv_rms_vec: V16 = @splat(inv_rms);
    const inv_rms_cubed_vec: V16 = @splat(inv_rms_cubed);
    const inv_n_vec: V16 = @splat(1.0 / n_f32);

    var sum_gwx_vec: V16 = @splat(0.0);
    offset = 0;
    while (offset < full) : (offset += 16) {
        const g = loadF32x16(grad_output, offset);
        const x = loadF32x16(input, offset);
        const w = loadF32x16(weight, offset);
        sum_gwx_vec += g * w * x;
    }

    var total_sum_gwx = @reduce(.Add, sum_gwx_vec);
    while (offset < N) : (offset += 1) {
        total_sum_gwx += bf16ToF32(grad_output[offset]) * bf16ToF32(weight[offset]) * bf16ToF32(input[offset]);
    }

    const sum_gwx_splat: V16 = @splat(total_sum_gwx);

    offset = 0;
    while (offset < full) : (offset += 16) {
        const g = loadF32x16(grad_output, offset);
        const x = loadF32x16(input, offset);
        const w = loadF32x16(weight, offset);
        const grad_in = (w * inv_rms_vec * g) - (x * sum_gwx_splat * inv_rms_cubed_vec * inv_n_vec);
        const grad_w = g * x * inv_rms_vec;
        storeF32x16(grad_input, offset, grad_in);
        storeF32x16(grad_weight, offset, grad_w);
    }

    while (offset < N) : (offset += 1) {
        const g = bf16ToF32(grad_output[offset]);
        const x = bf16ToF32(input[offset]);
        const w = bf16ToF32(weight[offset]);
        grad_input[offset] = f32ToBf16((w * inv_rms * g) - (x * total_sum_gwx * inv_rms_cubed / n_f32));
        grad_weight[offset] = f32ToBf16(g * x * inv_rms);
    }
}

pub fn layerNormBackward(comptime N: usize, grad_output: *const [N]u16, input: *const [N]u16, weight: *const [N]u16, grad_input: *[N]u16, grad_weight: *[N]u16, grad_bias: *[N]u16, eps: f32) void {
    if (N == 0) return;
    const full = (N / 16) * 16;
    var sum: V16 = @splat(0.0);
    var sum_sq: V16 = @splat(0.0);
    var offset: usize = 0;

    while (offset < full) : (offset += 16) {
        const x = loadF32x16(input, offset);
        sum += x;
        sum_sq += x * x;
    }

    var total_sum = @reduce(.Add, sum);
    var total_sum_sq = @reduce(.Add, sum_sq);
    while (offset < N) : (offset += 1) {
        const x = bf16ToF32(input[offset]);
        total_sum += x;
        total_sum_sq += x * x;
    }

    const n_f32: f32 = @floatFromInt(N);
    const mean = total_sum / n_f32;
    const mean_sq = total_sum_sq / n_f32;
    const variance = @max(mean_sq - (mean * mean), @as(f32, 0.0));
    const inv_std = safeInvSqrt(variance + eps);
    const inv_std_cubed = inv_std * inv_std * inv_std;

    const mean_vec: V16 = @splat(mean);
    const inv_std_vec: V16 = @splat(inv_std);
    const inv_std_cubed_vec: V16 = @splat(inv_std_cubed);
    const inv_n_vec: V16 = @splat(1.0 / n_f32);

    var sum_grad_centered_vec: V16 = @splat(0.0);
    var sum_grad_centered_xhat_vec: V16 = @splat(0.0);
    offset = 0;

    while (offset < full) : (offset += 16) {
        const x = loadF32x16(input, offset);
        const g = loadF32x16(grad_output, offset);
        const w = loadF32x16(weight, offset);
        const centered = x - mean_vec;
        const grad_centered = g * w;
        sum_grad_centered_vec += grad_centered;
        sum_grad_centered_xhat_vec += grad_centered * centered;
    }

    var total_sum_grad_centered = @reduce(.Add, sum_grad_centered_vec);
    var total_sum_grad_centered_xhat = @reduce(.Add, sum_grad_centered_xhat_vec);
    while (offset < N) : (offset += 1) {
        const x = bf16ToF32(input[offset]);
        const g = bf16ToF32(grad_output[offset]);
        const w = bf16ToF32(weight[offset]);
        const centered = x - mean;
        const grad_centered = g * w;
        total_sum_grad_centered += grad_centered;
        total_sum_grad_centered_xhat += grad_centered * centered;
    }

    const sum_grad_centered_splat: V16 = @splat(total_sum_grad_centered);
    const sum_grad_centered_xhat_splat: V16 = @splat(total_sum_grad_centered_xhat);

    offset = 0;
    while (offset < full) : (offset += 16) {
        const x = loadF32x16(input, offset);
        const g = loadF32x16(grad_output, offset);
        const w = loadF32x16(weight, offset);
        const centered = x - mean_vec;
        const term1 = g * w * inv_std_vec;
        const term2 = sum_grad_centered_splat * inv_std_vec * inv_n_vec;
        const term3 = centered * sum_grad_centered_xhat_splat * inv_std_cubed_vec * inv_n_vec;
        const grad_in = term1 - term2 - term3;
        const grad_w = g * centered * inv_std_vec;
        storeF32x16(grad_input, offset, grad_in);
        storeF32x16(grad_weight, offset, grad_w);
        storeF32x16(grad_bias, offset, g);
    }

    while (offset < N) : (offset += 1) {
        const x = bf16ToF32(input[offset]);
        const g = bf16ToF32(grad_output[offset]);
        const w = bf16ToF32(weight[offset]);
        const centered = x - mean;
        grad_input[offset] = f32ToBf16((g * w * inv_std) - (total_sum_grad_centered * inv_std / n_f32) - (centered * total_sum_grad_centered_xhat * inv_std_cubed / n_f32));
        grad_weight[offset] = f32ToBf16(g * centered * inv_std);
        grad_bias[offset] = f32ToBf16(g);
    }
}

pub fn softmaxBackward(comptime N: usize, grad_output: *const [N]u16, output: *const [N]u16, grad_input: *[N]u16) void {
    if (N == 0) return;
    const full = (N / 16) * 16;
    var dot_vec: V16 = @splat(0.0);
    var offset: usize = 0;

    while (offset < full) : (offset += 16) {
        const s = loadF32x16(output, offset);
        const g = loadF32x16(grad_output, offset);
        dot_vec += s * g;
    }

    var total_dot = @reduce(.Add, dot_vec);
    while (offset < N) : (offset += 1) {
        total_dot += bf16ToF32(output[offset]) * bf16ToF32(grad_output[offset]);
    }

    const dot_splat: V16 = @splat(total_dot);

    offset = 0;
    while (offset < full) : (offset += 16) {
        const s = loadF32x16(output, offset);
        const g = loadF32x16(grad_output, offset);
        storeF32x16(grad_input, offset, s * (g - dot_splat));
    }

    while (offset < N) : (offset += 1) {
        const s = bf16ToF32(output[offset]);
        const g = bf16ToF32(grad_output[offset]);
        grad_input[offset] = f32ToBf16(s * (g - total_dot));
    }
}

pub fn geluBackward(comptime N: usize, grad_output: *const [N]u16, input: *const [N]u16, grad_input: *[N]u16) void {
    const full = (N / 16) * 16;
    const sqrt_2_over_pi: V16 = @splat(0.7978845608028654);
    const coeff_0_044715: V16 = @splat(0.044715);
    const coeff_3_044715: V16 = @splat(0.134145);
    const half: V16 = @splat(0.5);
    const one: V16 = @splat(1.0);
    var offset: usize = 0;

    while (offset < full) : (offset += 16) {
        const x = loadF32x16(input, offset);
        const g = loadF32x16(grad_output, offset);
        const x2 = x * x;
        const x3 = x2 * x;
        const tanh_arg = sqrt_2_over_pi * (x + (coeff_0_044715 * x3));
        const tanh_val = tanhApprox16(tanh_arg);
        const sech_sq = one - (tanh_val * tanh_val);
        const inner_deriv = sqrt_2_over_pi * (one + (coeff_3_044715 * x2));
        const deriv = half * (one + tanh_val) + (half * x * sech_sq * inner_deriv);
        storeF32x16(grad_input, offset, g * deriv);
    }

    while (offset < N) : (offset += 1) {
        const x = bf16ToF32(input[offset]);
        const g = bf16ToF32(grad_output[offset]);
        const tanh_arg = 0.7978845608028654 * (x + 0.044715 * x * x * x);
        const tanh_val = tanhApproxScalar(tanh_arg);
        const sech_sq = 1.0 - (tanh_val * tanh_val);
        const inner_deriv = 0.7978845608028654 * (1.0 + 0.134145 * x * x);
        const deriv = 0.5 * (1.0 + tanh_val) + 0.5 * x * sech_sq * inner_deriv;
        grad_input[offset] = f32ToBf16(g * deriv);
    }
}
